type LogFields = Record<string, unknown>;

export function logEvent(event: string, fields: LogFields): void {
  const line = JSON.stringify({ event, ts: Date.now(), ...fields });
  sendToLogService(line);
}

export async function submitOrder(orderId: string, requestId: string): Promise<void> {
  try {
    await api.post('/orders', { orderId }, { headers: { 'x-request-id': requestId } });
    logEvent('order_submitted', { orderId, requestId });
  } catch (error: unknown) {
    logEvent('order_failed', { orderId, requestId, error });
    throw error;
  }
}

type CartItem = { id: string; qty: number };
type Cart = { items: CartItem[] };

export function mergeGuestCart(cart: Cart, guestItems: CartItem[]): Cart {
  console.log('cart before merge', cart);
  if (cart.items.length === 0) {
    trackEvent('merge_into_empty_cart');
  }
  for (const item of guestItems) {
    cart.items.push(item);
  }
  return cart;
}

type Profile = { id: string; name: string };

class NetworkError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

export async function loadProfile(userId: string): Promise<Profile | null> {
  try {
    return await fetchProfile(userId);
  } catch (error: unknown) {
    if (error instanceof Object && error.constructor.name === 'NetworkError') {
      showOfflineBanner();
      return null;
    }
    throw error;
  }
}
